"""H412 core/additions/remainder decomposition across source heads."""
import json,hashlib
import numpy as np
import torch
import torch.nn.functional as F
from run_bilin18_l17_local_residual_charts import ROOT,ART,load_full_model,collect_sources
from run_bilin18_l17_native_sensitivity_factors import drms
from run_bilin18_l17_fisher_ranked_factors import native_drms
STEM=ART/'bilin18_l17_factor_group_roles'
@torch.inference_mode()
def main():
 torch.set_num_threads(6);cfg=json.loads((ROOT/'configs'/f'{STEM.name}.json').read_text());op=ART/'bilin18_l17_residual_factor_rescue_frozen_sets.npz';prior=ART/'bilin18_l17_rescue_transfer_confirmation_rows.npz';assert hashlib.sha256(op.read_bytes()).hexdigest()==cfg['sets_sha256'];assert hashlib.sha256(prior.read_bytes()).hexdigest()==cfg['prior_rows_sha256'];assert hashlib.sha256((ROOT/cfg['corpus']).read_bytes()).hexdigest()==cfg['corpus_sha256'];q=np.load(op);core=q['core'];union=q['sets128'][0];addition=union[64:];assert np.array_equal(core,union[:64]);assert not set(core)&set(addition);ci=torch.tensor(core,device='cuda');ai=torch.tensor(addition,device='cuda');ui=torch.tensor(union,device='cuda');model=load_full_model('cuda');model.embedding.float();model.blocks.float();model.lm_head.float();pre,heads,_=collect_sources(model,np.load(ROOT/cfg['corpus']),cfg);S=len(pre);L,R,D=[m.weight.detach() for m in [model.blocks[17].mlp.Left,model.blocks[17].mlp.Right,model.blocks[17].mlp.Down]];Dd=D.double();W=model.lm_head.weight.double();x=F.rms_norm(pre,(1152,));lx=x@L.T;rx=x@R.T;phi0=lx*rx;m0=phi0@D.T;state=pre+m0+model.blocks[17].mlp.Down_bias;base=F.rms_norm(state,(1152,));tm=np.empty((9,6,S));full_energy=np.empty((9,S));finite=np.empty((9,2,S));effect=np.empty((9,S));closure=0.;direct_error=0.;vector_error=0.
 def lp(y):return (30*torch.tanh((y.double()@W.T)/30)).log_softmax(-1)
 for h in range(9):
  u=drms(pre,-heads[:,h]);phi=((u@L.T)*rx+lx*(u@R.T)).double();full=phi@Dd.T;c=phi[:,ci]@Dd[:,ci].T;a=phi[:,ai]@Dd[:,ai].T;o=full-c-a;xx=F.rms_norm(pre-heads[:,h],(1152,));phi1=(xx@L.T)*(xx@R.T);r=phi1@D.T-m0;delta=phi1-phi0;add=delta[:,ai]@D[:,ai].T;target=F.rms_norm(state+r,(1152,));pred=F.rms_norm(state+add,(1152,));clamp=F.rms_norm(state+r-add,(1152,));patch=phi1[:4].clone();patch[:,ai]=phi0[:4,ai];direct=F.rms_norm(pre[:4]+patch@D.T+model.blocks[17].mlp.Down_bias,(1152,));direct_error=max(direct_error,float((direct-clamp[:4]).abs().max()));joined=delta[:,ui]@D[:,ui].T;parts=delta[:,ci]@D[:,ci].T+add;vector_error=max(vector_error,float(((joined-parts).norm(dim=-1)/joined.norm(dim=-1)).max()))
  for off in range(0,S,16):
   sl=slice(off,off+16);s=state[sl].double();raw=base[sl].double()@W.T;th=torch.tanh(raw/30);cap=1-th.square();p=(30*th).softmax(-1);ts=[]
   for v in [c,a,o]:
    t=(native_drms(s,v[sl])@W.T)*cap;t-=(p*t).sum(-1,keepdim=True);ts.append(t)
   tc,ta,to=ts;t=tc+ta+to;f=(p*t.square()).sum(-1);vals=torch.stack([(p*tc.square()).sum(-1),(p*ta.square()).sum(-1),(p*to.square()).sum(-1),2*(p*tc*ta).sum(-1),2*(p*tc*to).sum(-1),2*(p*ta*to).sum(-1)]);tm[h,:,sl]=vals.cpu().numpy();full_energy[h,sl]=f.cpu().numpy();closure=max(closure,float(((vals.sum(0)-f).abs()/f).max()));pt=lp(target[sl]);p0=(30*th).log_softmax(-1);pp=lp(pred[sl]);pc=lp(clamp[sl]);effect[h,sl]=(pt.exp()*(pt-p0)).sum(-1).cpu().numpy();finite[h,0,sl]=(pt.exp()*(pt-pp)).sum(-1).cpu().numpy();finite[h,1,sl]=(pc.exp()*(pc-p0)).sum(-1).cpu().numpy()
  np.savez_compressed(STEM.with_name(STEM.name+'_partial_rows.npz'),tangent_metrics=tm[:h+1],full_energy=full_energy[:h+1],additions_finite=finite[:h+1],native_effect=effect[:h+1]);print('head',h,'complete',flush=True)
 assert np.isfinite(tm).all() and np.isfinite(finite).all();audit={'Fisher_energy_identity_max_relative':closure,'direct_additions_clamp_state_max_absolute':direct_error,'finite_core_plus_add_union_relative_error':vector_error};STEM.with_name(STEM.name+'_audit.json').write_text(json.dumps(audit,indent=2)+'\n');np.savez_compressed(STEM.with_name(STEM.name+'_rows.npz'),tangent_metrics=tm,full_energy=full_energy,additions_finite=finite,native_effect=effect);analyze(cfg,tm,full_energy,finite,effect,audit)
def analyze(cfg,tm,fe,m,e,audit):
 old=np.load(ART/'bilin18_l17_rescue_transfer_confirmation_rows.npz');audit['native_effect_replay_max_absolute']=float(abs(e-old['native_effect'][:9]).max());allm=np.stack([old['metrics'][0,:9],m,old['metrics'][1,:9]]);n=cfg['rows'];td=tm.reshape(9,6,n,4).mean(-1);fd=fe.reshape(9,n,4).mean(-1);d=allm.reshape(3,9,2,n,4).mean(-1);ed=e.reshape(9,n,4).mean(-1)
 def summary(ix):
  cross=td[:,3][:,ix].mean(-1)/fd[:,ix].mean(-1);rec=1-d[:,:,0][:,:,ix].mean(-1)/ed[:,ix].mean(-1)[None];return np.r_[cross,rec[1],rec[1]-rec[0]]
 point=summary(np.arange(n));rng=np.random.default_rng(cfg['bootstrap_seed']);boot=np.stack([summary(rng.integers(0,n,n)) for _ in range(cfg['bootstrap_samples'])]);rad=np.quantile(abs(boot-point).max(1),.95);ci=np.stack([point-rad,point+rad],-1);gates={'energy_identity':audit['Fisher_energy_identity_max_relative']<1e-8,'native_replay':audit['native_effect_replay_max_absolute']<1e-10,'head6_cancellation05':bool(ci[6,1]<-.05),'heads3_4_additions_over_core10':bool((ci[[21,22],0]>.1).all()),'all_additions80':bool((ci[9:18,0]>.8).all()),'any_positive_cross05':bool((ci[:9,0]>.05).any())};j={'config':cfg,'tangent_metric_names':['core_energy','additions_energy','remainder_energy','core_add_cross','core_remainder_cross','add_remainder_cross'],'mean_tangent_metrics':tm.mean(-1).tolist(),'mean_full_energy':fe.mean(-1).tolist(),'finite_methods':['core64','additions64','union128'],'finite_metric_names':['prediction_KL','clamped_remaining_KL'],'mean_finite_metrics':allm.mean(-1).tolist(),'mean_native_effect':e.mean(-1).tolist(),'primary_names':['core_add_cross_over_full_each_head','additions_only_finite_recovery_each_head','additions_minus_core_finite_recovery_each_head'],'primary':point.tolist(),'primary_joint27_ci95':ci.tolist(),'gates':gates,'audit':audit};STEM.with_suffix('.json').write_text(json.dumps(j,indent=2)+'\n');np.savez_compressed(STEM.with_name(STEM.name+'_bootstrap.npz'),primary=boot);print('FINISHED',gates,point,flush=True)
if __name__=='__main__':main()
